import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';
import 'package:postbox_game/monarch_info.dart';
import 'package:postbox_game/theme.dart';

/// A royal cypher drawn as it is cast on a postbox door: the crown over the
/// monarch's letters, with the regnal number between them.
///
/// The artwork lives in `assets/cyphers/`, generated by
/// `tool/cypher_art/build_cypher_svgs.py`. The files are single-colour, so
/// [color] tints them. With [embossed] a dark copy sits 1.5 dp lower, so the
/// letters look raised like a casting.
///
/// The art fills its constraints at the shared aspect ratio. Pass [height]
/// to fix its size instead. It is decorative: whatever shows it must also
/// name the cypher (in text or a semantics label).
class CypherArt extends StatelessWidget {
  const CypherArt(
    this.code, {
    super.key,
    this.height,
    this.color = parchment,
    this.embossed = false,
  });

  final String code;
  final double? height;
  final Color color;
  final bool embossed;

  /// The viewBox aspect (200 x 160) shared by every file in assets/cyphers/.
  static const double aspectRatio = 200 / 160;

  /// The asset for [code], or null if it has none: anything outside
  /// [MonarchInfo.all], such as [MonarchInfo.plainKey].
  static String? assetFor(String code) => MonarchInfo.all.contains(code)
      ? 'assets/cyphers/${code.toLowerCase()}.svg'
      : null;

  @override
  Widget build(BuildContext context) {
    final asset = assetFor(code);
    Widget art(Color tint) => asset == null
        ? const SizedBox.expand()
        : SvgPicture.asset(
            asset,
            fit: BoxFit.contain,
            colorFilter: ColorFilter.mode(tint, BlendMode.srcIn),
            excludeFromSemantics: true,
          );
    Widget child = embossed
        ? Stack(
            fit: StackFit.expand,
            children: [
              Transform.translate(
                offset: const Offset(0, 1.5),
                child: art(Colors.black.withValues(alpha: 0.45)),
              ),
              art(color),
            ],
          )
        : art(color);
    child = AspectRatio(aspectRatio: aspectRatio, child: child);
    if (height != null) {
      child = SizedBox(height: height, width: height! * aspectRatio, child: child);
    }
    return child;
  }
}

/// [CypherArt] in cream on a postal-red "door plate", the way the quiz tiles,
/// the watch quiz and the Cypher guide show a cypher.
///
/// [MonarchInfo.plainKey] (or any code without artwork) gets a plain plate
/// with a dash. The plate fills the available width unless [width] is given.
class CypherPlate extends StatelessWidget {
  const CypherPlate(
    this.code, {
    super.key,
    this.height = 80,
    this.width,
    this.embossed = true,
  });

  final String code;
  final double height;
  final double? width;
  final bool embossed;

  static const Color _plateTop = Color(0xFFD8243F);
  static const Color _plateBottom = Color(0xFFA50D26);
  static const Color _plateEdge = Color(0xFF7D0A1D);

  @override
  Widget build(BuildContext context) {
    final topRadius = (height * 0.12).clamp(4.0, 10.0);
    return ExcludeSemantics(
      child: Container(
        height: height,
        width: width,
        padding: EdgeInsets.symmetric(
          vertical: height * 0.1,
          horizontal: height * 0.08,
        ),
        decoration: BoxDecoration(
          gradient: const LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [_plateTop, postalRed, _plateBottom],
            stops: [0, 0.55, 1],
          ),
          border: Border.all(color: _plateEdge),
          borderRadius: BorderRadius.vertical(
            top: Radius.circular(topRadius),
            bottom: Radius.circular(topRadius / 2),
          ),
        ),
        child: Center(
          child: CypherArt.assetFor(code) == null
              ? Text(
                  '—',
                  style: TextStyle(
                    color: parchment,
                    fontSize: height * 0.4,
                    fontWeight: FontWeight.bold,
                    height: 1,
                  ),
                )
              : CypherArt(code, embossed: embossed),
        ),
      ),
    );
  }
}
